function num(v) {
  return Number(String(v ?? '0').replace(/[^\d,.-]/g, '').replace(',', '.')) || 0;
}
function reais(n) {
  return n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

const itens = $input.all().map((i) => i.json);
const por = (s) => itens.filter((o) => String(o.status || '').trim() === s);

const abertos = por('enviado');
const responderam = por('respondeu');
const recuperados = por('recuperado');
const perdidos = por('perdido');

const valorAberto = abertos.reduce((s, o) => s + num(o.valor), 0);
const valorRecuperado = recuperados.reduce((s, o) => s + num(o.valor), 0);
const valorPerdido = perdidos.reduce((s, o) => s + num(o.valor), 0);

const tocados = itens.filter((o) => String(o.ultimo_toque || '').trim() !== '');
const reagiram = tocados.filter((o) => ['respondeu', 'recuperado'].includes(String(o.status || '').trim()));
const taxa = tocados.length ? Math.round((reagiram.length / tocados.length) * 100) : 0;

let msg = '📊 *Móveis Premium — resumo da semana*\n\n';
msg += `💰 Recuperado: *R$ ${reais(valorRecuperado)}* (${recuperados.length} orçamento(s) fechado(s) após follow-up)\n`;
msg += `🔥 Aguardando o vendedor: ${responderam.length} cliente(s) que responderam\n`;
msg += `⏳ Em aberto: ${abertos.length} orçamento(s) — R$ ${reais(valorAberto)} em jogo\n`;
msg += `❌ Perdidos: ${perdidos.length} — R$ ${reais(valorPerdido)}\n\n`;
msg += `📈 Taxa de resposta ao follow-up: ${taxa}% (${reagiram.length} de ${tocados.length} contatados)\n`;

if (responderam.length > 0) {
  msg += '\n*Clientes esperando contato:*\n';
  msg += responderam
    .map((o) => `• ${o.cliente} — ${o.descricao} (R$ ${reais(num(o.valor))}) → ${o.vendedor}`)
    .join('\n');
}

if (abertos.length > 0) {
  msg += '\n\n_Os orçamentos em aberto seguem recebendo follow-up automático._';
}

return [{ json: { para: 'NUMERO_DO_DONO', mensagem: msg, valor_recuperado: valorRecuperado, taxa_resposta: taxa } }];
